int main(void) {
    const uint64_t zero[4] = {0, 0, 0, 0};
    const int n = (int) (sizeof cases / sizeof cases[0]);
    for (int i = 0; i < n; ++i) {
        const Case* c = &cases[i];
        int actual = mla_full_resident_budget(c->free, c->reserve, c->expert,
            c->parts, c->parts + 4, c->cap, c->explicit_limit, c->allowed);
        if (actual != c->expected) { fprintf(stderr, "forecast case%d: %d != %d\n", i, actual, c->expected); return 1; }
    }
    if (mla_full_resident_budget(UINT64_MAX, 0, 0, NULL, zero, 1, 0, 0) ||
        mla_full_resident_budget(UINT64_MAX, 0, 0, zero, NULL, 1, 0, 0)) return 1;
    printf("full-resident allocation forecast: passed (%dchecks, CPU only)\n", n + 2);
    return 0;
}
